ROOT=Path(__file__).resolve().parents[1]
PROJECTS={
'video-guard':('VideoGuard-Lab','Audio-Visual Event Synchronization and Causal Drift Localization','音画事件同步、校准拒估与因果漂移定位','由独立 RGB 与 PCM 合成事件估计音画延时，将相关性基线、共享 MLP 与双塔 InfoNCE 放在同一实验协议下比较。进一步检查概率校准、预测集合、局部矛盾及实际报警时间。项目保留负对照、失败样本和跨语言推断一致性，不将合成域结果当作自然视频性能。',['合成 RGB / PCM','相关性与 MLP 对照','校准与预测集合','因果窗口与报警'],'已有合成媒体轨迹再分析；±800ms 定位容差，500–2000ms 报警时限。','artifacts/drift-localization/REPORT.md'),
'reliability-lab':('FlowBench','Fault Injection, Bounded Retry and Idempotent Workflow Recovery','AI 工作流的有限重试、幂等恢复与证据回放','围绕模型之外的执行可靠性，构建 ingest、retrieve、analyze、validate、commit 五阶段工作流。对照单次执行、有限重试与本地幂等恢复，在同一故障清单下记录排队、失败时延、检查点和提交副作用。新增实验按故障、并发与固定种子拆分，并单独验证 SQLite 重开后的恢复行为。',['固定故障清单','异步 DAG 执行','重试 / 检查点','副作用与轨迹核验'],'81 次受控本地异步运行；每次 16 个任务，非生产事故或真实 LLM 评测。','results/advanced/REPORT.md'),
'cite-rag':('CiteRAG','Hybrid Retrieval, Evidence Attribution and Content Deduplication','混合检索、引用归因与内容去重','在自建小型知识语料中比较 BM25、字符三元组与 RRF 混合检索。输出为现有证据摘录，不伪装成 LLM 生成；证据不足时拒答。深化实验引入内容指纹去重，对照重复文档和无关文档注入下的排名变化，保留逐问题引用、指纹和失败状态。',['自建问题与语料','BM25 / 字符检索','RRF 与内容去重','摘录 / 引用 / 拒答'],'25 个自建问题；六组条件，成功定义为 top-3 召回或正确拒答，不是答案语义准确率。','artifacts/REPORT.md'),
'textguard':('TextGuard','Interpretable Text Classification and Lexical Robustness','可解释短文本分类与词项鲁棒性','使用旧英语短信研究数据训练 TF-IDF 与 Logistic Regression，比较朴素贝叶斯基线，并导出数值参数在浏览器推断。训练、验证与测试按固定协议分离，保留误判和权重贡献。深化实验检查大小写、标点、空白、拼写、否定与未知语言前缀，并将覆盖率与错误率共同报告。',['去重与数据划分','TF-IDF / Logistic','数值导出与词项贡献','变形探针与留出复查'],'20 个自建探针 × 6 种变形；标签由作者定义，不代表现代诈骗或中文分类表现。','artifacts/REPORT.md'),
'novelty-lab':('NoveltyLab','Novelty Detection under Feature Perturbation and Distribution Shift','特征扰动与分布迁移下的新颖性检测','将 Wine 类别 0 人为定义为正常分布，其他类别用于受控迁移评估。标准化只在正常训练上拟合，阈值仅从正常验证选择；比较中心距离、Isolation Forest 与 One-Class SVM。深化实验逐维施加标准化扰动，复查决策翻转和相对拟合中心的平方距离贡献。',['正常训练分布','标准化与中心拟合','验证阈值 / 模型对照','逐维扰动与翻转'],'131 条历史留出 × 13 维 × 5 种扰动幅度；相关变体不是独立样本。','artifacts/REPORT.md'),
'vision-cal':('VisionCal','Probability Calibration and Robustness of a Small Neural Classifier','小型神经网络的概率校准与视觉扰动','实际训练 64→48→10 MLP，使用验证集冻结温度参数，对照原概率和温度缩放。噪声、平移和中心遮挡用于检查脆弱性；分别报告分类正确率、NLL、覆盖与高置信错误。温度只改变概率，不改变 argmax 标签，公开 8×8 样本不代表通用 OCR。',['公开 8×8 图像','MLP 与验证温度','固定种子扰动','概率 / 覆盖 / 错误'],'360 条历史留出 ID，8 种条件；不使用测试结果重新选择温度。','artifacts/REPORT.md'),
'tiny-attention':('TinyAttention','Causal Attention, Ablation and Length Generalization','因果注意力、消融与长度外推','从小型单块 Transformer 的合成键值查找任务出发，实现因果 mask、残差和 LayerNorm，并保留无注意力消融与长度外推。深化部分独立实现 NumPy 推断，逐前缀检查因果数值一致性；新前缀排除原训练、验证和测试 ID，另外检查重新排序与未知查询。',['合成键值前缀','因果 Attention','独立 NumPy 推断','长度 / 顺序 / 未知查询'],'每个长度 120 个新前缀；因果正确性不等于任务泛化，注意力权重不是因果解释。','artifacts/REPORT.md'),
'lora-lab':('LoRA-Lab','Low-Rank Adaptation, Weight Merging and Task Retention','低秩适配、权重合并与旧任务保留','使用本仓库 TinyAttention 基座进行低秩适配，原实验比较 rank 1 / 4 与全量微调。深化实验重构 q、v 和输出头的实际 A/B 增量，检查与 merged 导出的一致性，并在相同新前缀上分别评价旧规则与新规则。参数强度扫描是诊断，而不是在测试上选最优配置。',['共享冻结基座','q / v / head 低秩增量','合并数值校验','新旧规则分别评估'],'固定 rank 4，六档适配强度；160 个新前缀，不外推大模型显存或生产收益。','artifacts/REPORT.md'),
'dpo-lab':('DPO-Lab','Preference Optimization, Probability Ranking and Policy Drift','偏好优化、概率排序与策略漂移','在合成单 token 偏好任务中实现 DPO、冻结 reference 与 chosen-only SFT 对照。深化实验对冻结输出头进行六档插值，分别计算 pair win、chosen top-1、KL 与原任务保留，避免将偏好赢率当作答案正确率。新前缀排除旧数据 ID，插值不等价于重新训练 beta。',['规则偏好与 reference','Head-only DPO','六档输出头插值','Win / Top-1 / KL / 保留'],'180 个新合成前缀；不是人类偏好标注、真人对齐或安全性验证。','artifacts/REPORT.md'),
'moe-lab':('SparseMoE','Expert Capacity, Sparse Routing and Overflow Handling','专家容量、稀疏路由与溢出处理','实现四个小型专家的 top-1 分发，比较负载平衡与两种 dense 基线。深化实验限制每个专家容量，对照丢弃归零与第二选择路由。在均匀和偏斜输入中共同报告全批误差、接收覆盖率、接收项误差及负载，丢弃项不会从全批结果中消失。',['路由概率与专家','有序容量分发','丢弃 / 第二选择','覆盖与全批误差'],'两批各 256 个新样本；容量 0.5 / 1 / 1.5 / 不限，非分布式 AllToAll 吞吐测试。','artifacts/REPORT.md'),
'spec-decode':('SpecDecode','Greedy Speculative Decoding and Incremental KV Cache','Greedy 推测解码与增量 KV 缓存','训练独立 draft / target 小模型，以 greedy 块验证核验逐 token 输出一致性。深化实验实现真实单层 K/V 增量缓存，对照完整前缀重算，并记录 k=1 / 2 / 4 的逐块接受与修正轨迹。实际本机计时包含预热和交替顺序，目标调用次数减少不等于加速。',['Draft / Target','Greedy 草稿块验证','单层 K/V 增量缓存','一致性与配对计时'],'24 个新四 token 前缀，8 个输出，三次配对计时；非随机采样或 GPU 加速实验。','artifacts/REPORT.md'),
'circuit-id':('CircuitID','RC System Identification with Unknown Gain and Offset','未知增益与偏置下的 RC 系统辨识','由带噪 RC 阶跃波形估计时间常数，比较规则、单位输入物理拟合和冻结学习模型。深化实验以变量投影联合估计增益、偏置与时间常数，在单位、增益变化、偏置变化及组合条件中复查误差和残差。只从阶跃辨识时间常数，不把仿真参数当作设备测量。',['32 点合成阶跃','物理 / Ridge 对照','变量投影联合拟合','重建波形与残差'],'400 条新仿真曲线，时间常数 0.5–6ms；无硬件实测、设备控制或容差保证。','artifacts/REPORT.md'),
'channel-est':('ChannelEst','Pilot-Based Channel Estimation with Missing Observations','缺失观测下的导频信道估计','在理想频域通信仿真中，由稀疏导频估计复信道，并比较插值、学习 Ridge、LMMSE 与真 CSI。深化实验比较缺失导频零填充的冻结估计器与观测导频 LS；少于四个观测时显式拒估。结果主要用 NMSE 解释，已知四径模型给 LS 带来的先验优势单列。',['合成四径信道','缺失导频掩码','冻结模型 / 观测 LS','NMSE 与欠定拒估'],'160 条新信道，20dB；0 / 1 / 2 / 4 / 6 个缺失导频，非射频设备或 5G/6G 产品。','artifacts/REPORT.md'),
'power-scope':('PowerScope','Data-Center Load Forecasting and Cooling-Drift Diagnostics','数据中心负荷预测与冷却漂移诊断','以透明作业计划、IT 负载和冷却合成模型构建下一步负荷预测，对照持久性、季节和 Ridge。深化实验只分析已冻结的时间留出与漂移预测：按日查看误差、偏差和覆盖率，比较区间宽度并复算线性贡献。扩大区间不等于解决漂移，页面只读，不连接或控制电气设备。',['合成负荷与计划','时间留出预测','逐日残差与漂移','区间覆盖 / 贡献复算'],'历史冻结预测再分析，每块 288 点；时序相关性不支持独立样本置信保证。','artifacts/REPORT.md')}
